"""Small, strict schemas. No arbitrary URLs, SQL, shell or file tools."""


def function(name, description, properties):
    return {"type": "function", "name": name, "description": description,
            "strict": True, "parameters": {"type": "object", "properties": properties, "required": list(properties), "additionalProperties": False}}


STR = {"type": "string"}
IDS = {"type": "array", "items": STR, "minItems": 1, "maxItems": 6}
NULLINT = {"type": ["integer", "null"], "minimum": 0, "maximum": 20000}
LEGACY_TOOLS = [
    function("map_view", "Focus the existing map and enable requested layers. Layer names do not prove data availability.", {
        "layer_ids": {"type":"array","items":{"type":"string","enum":["population","parcels","planning","land-price","flood-history","flood-satellite","flood-risk","rain","public-buildings","traffic","green-space","road-density"]}},
        "bbox":{"type":["array","null"],"items":{"type":"number"},"minItems":4,"maxItems":4}}),
    function("find_sites", "Filter installed canonical parcel data. Cannot establish vacancy, legal permission or low flood risk from missing observations.", {
        "minimum_area_m2":{"type":"number","minimum":0,"maximum":100000},"maximum_area_m2":{"type":"number","minimum":500,"maximum":100000},
        "land_use_codes":{"type":"array","items":STR},"bbox":{"type":["array","null"],"items":{"type":"number"},"minItems":4,"maxItems":4},"limit":{"type":"integer","minimum":1,"maximum":12}}),
    function("inspect_parcels", "Read source attributes, source planning flags and coverage for user-selected/candidate parcels.", {"parcel_ids":IDS}),
    function("read_context", "Read source context near selected parcels: reported flood history, rainfall-threshold risk, satellite classifications, road price references or OSM services. Missing data never means safe, vacant or cheap.", {
        "layer":{"type":"string","enum":["flood_history","flood_risk","flood_satellite","land_price","public_services"]},
        "parcel_ids":IDS,"buffer_m":{"type":"number","minimum":0,"maximum":1000},"limit":{"type":"integer","minimum":1,"maximum":10}}),
    function("prepare_simulation", "Prepare a stored draft and preflight. Do not invent program numbers. Ask missing floors/GFA/occupancy first. Explicit synthetic mode is a fictional scenario.", {
        "parcel_ids":IDS,"grouped":{"type":"boolean"},"mode":{"type":"string","enum":["site_selection","cumulative"]},
        "use":{"type":"string","enum":["residential","office","school","hospital"]},"floors":{"type":"integer","minimum":1,"maximum":100},
        "floor_area_m2":{"type":"number","minimum":100,"maximum":500000},"housing_units":NULLINT,"residents":NULLINT,"staff":NULLINT,"daily_users":NULLINT,"service_capacity":NULLINT,
        "background_mode":{"type":"string","enum":["sourced","synthetic_capacity_v1"]}}),
    function("start_simulation", "Start an asynchronous solver job from a draft. Native requires UI authorization and bounded work; never claim queued jobs finished.", {"draft_id":STR,"mode":{"type":"string","enum":["screening","native"]}}),
    function("read_results", "Read owned job status and measured model results for explanation/comparison. Delay must be discussed with completion/backlog and seeds.", {"job_ids":{"type":"array","items":STR,"minItems":1,"maxItems":8}}),
    function("suggest_and_verify", "Create a bounded design variant preserving building program, queue baseline and variant for comparison. No improvement claim until results finish. School/location goals use alternative parcel comparison instead.", {
        "draft_id":STR,"goal":{"type":"string","enum":["water","power","runoff","traffic"]},"mode":{"type":"string","enum":["screening","native"]}}),
]

TEXT = {"type":"string"}
NULLTEXT = {"type":["string","null"]}
BOUNDS = {"type":["array","null"],"items":{"type":"number"},"minItems":4,"maxItems":4}
MODE = {"type":"string","enum":["screening","native"]}
TOOLS = [
    function('dataset_describe','Discover actual observed fields/types/examples, metadata, units and query syntax for any connected dataset in the selected area. Call before constructing structured filters; do not invent field names or unit conversions. Optional buffer_m (null=0) expands discovery for nearby join sources, e.g. roads outside a selected parcel. Empty source cannot establish its schema.',{'layer':TEXT,'buffer_m':{'type':['number','null'],'minimum':0,'maximum':5000}}),
    function('dataset_query','Read-only structured query over any connected source in the confirmed area. query_json: {layer,spatial:intersects|within,buffer_m:0..5000,where,joins,select,order_by,group_by,aggregates,limit:1..100,population_year,traffic_weekday,traffic_hour,start_date,end_date,run_id}. where uses {all:[...]},{any:[...]},{not:...} or {field,op,value}; ops eq/ne/gt/gte/lt/lte/between/in/contains/is_known/is_unknown. joins max3: {layer,alias,relation:near|intersects|within,radius_m,where}; source filters applied before choosing nearest qualifying feature. Join fields alias.<source property>, alias.distance_m, alias.observed_match, alias.match_count. Filter price.residential_vnd_m2 using VND/m², preserve review flags; these are nearby-road reference prices, never parcel values. order_by [{field,direction:asc|desc}], aggregates [{op:count|sum|avg|min|max,field:null|string}], group_by [field]. Null comparisons stay unknown. Scope/adapter limits and missing-source evidence must be disclosed; absence of records does not prove absence of hazard. Results appear as filtered geometry and evidence table. Population is area-total only, cannot be joined/allocated to parcels.',{'query_json':TEXT}),
    function('dataset_query_refine','Continue one of the last five owned queries in the same area. query_id from dataset_query; patch_json uses the same keys. New where is ANDed with old filters; other keys explicitly replace. Re-queries source rows before limiting, not only the previous displayed results. To replace/remove filters or change geography start dataset_query instead.',{'query_id':TEXT,'patch_json':TEXT}),
    function('platform_overview','Explain the full urban planning assistant, available data domains, workflow and limits. Does not require a plan.',{}),
    function('area_select','Choose analysis area independent of Development. For a named street or alley use source=street FIRST: queries actual team OSM/SUMO road names without external geocoding. query is only the street/alley name (e.g. Hẻm 114 Trần Quốc Tuấn), not district/city or house/floor instructions; bbox is optional location disambiguation, not the unrelated current viewport. Exact alley names take precedence over branches. Uses a disclosed 100m road buffer, not a legal alley/property boundary. If multiple matches and match_index is null, returns ambiguous_street without changing area; ask user to choose. source=place resolves city/district/public places via provider bbox. viewport uses visible bounds only when user requests/confirms that scope; parcel/plan/bbox use source/saved/explicit geometry. Use null for irrelevant fields.',{
        'source':{'type':'string','enum':['viewport','street','place','goong_place','parcel','plan','bbox']},'query':NULLTEXT,'parcel_id':NULLTEXT,'bbox':BOUNDS,'match_index':{'type':['integer','null'],'minimum':0,'maximum':7}}),
    function('area_analyze','Analyze selected area without opening a plan: modelled population for an explicit year, mapped footprints, roads, historical congestion, flood/rain/reference prices, installed services/transit/landcover. Optional traffic weekday/hour defaults to ISO Tuesday 18:00, historical not live. Optional ISO date filters apply only to time-enabled layers; unsupported filters are labelled. Missing source remains unknown; future model years are projections.',{'population_year':{'type':'integer','minimum':2010,'maximum':2040},'traffic_weekday':{'type':['integer','null'],'minimum':1,'maximum':7},'traffic_hour':{'type':['integer','null'],'minimum':0,'maximum':23},'start_date':NULLTEXT,'end_date':NULLTEXT}),
    function('candidate_search','Search source parcels in selected analysis area or explicit bbox, no plan required. Bounded first sample by area/ID, not a global best-site ranking. Do not call absence of buildings vacant land.',{'minimum_area_m2':{'type':'number'},'maximum_area_m2':{'type':'number'},'land_use_codes':{'type':'array','items':TEXT},'bbox':BOUNDS,'limit':{'type':'integer','minimum':1,'maximum':12}}),
    function('candidate_compare','Compare 2..6 source parcels using disclosed weighted criteria. criteria_json is [{metric,direction:minimize|maximize,weight,threshold?:number}]. Metrics: area_m2,population_density,road_distance_m,mapped_footprint_m2,transit_coverage_percent,mapped_green_m2. Explicitly explain chosen weights/proxies; ask preference if tradeoffs unclear. Common known criteria only; no zero imputation, no invented flood/cost/legal score. Returns detailed sources, unknowns and a comparison table.',{'parcel_ids':IDS,'criteria_json':TEXT,'population_year':{'type':'integer','minimum':2010,'maximum':2040}}),
    function('planning_review','Review current plan zoning coverage, scenario changes, building metrics and proposed-limit checks. Explicitly not authoritative legal approval.',{}),
    function('candidate_study_prepare','Prepare equal-program alternatives on 1..3 source parcels without a plan. For first N from the search MUST use selection=first_search,take=N,parcel_ids=[]; backend preserves the original search order, not ranked order. Otherwise selection=explicit with exact parcel IDs; take is ignored. program_json: use residential|school|office|hospital,floors,floor_area_m2,floor_height_m(default3.2),setback_m(default5),residents/housing_units for residential,staff/daily_users for others,service_capacity for school/hospital. Ask missing program, never invent occupancy. Preliminary square footprints preserve exact program; refuse sites failing the fit test. Existing occupancy/capacity unknown.',{'selection':{'type':'string','enum':['explicit','first_search']},'take':{'type':'integer','minimum':1,'maximum':3},'parcel_ids':{'type':'array','items':TEXT,'maxItems':3},'program_json':TEXT,'rainfall_mm':{'type':'number','minimum':0,'maximum':300}}),
    function('candidate_study_start','Start an owned equal-program multi-site study. Native gets one local OSM network/background for before/after and all options, bounded coverage/work. Requires UI native opt-in. Poll in UI rather than repeatedly calling model.',{'study_id':TEXT,'mode':MODE}),
    function('urban_results','Read owned multi-site study jobs and compare measured model outputs with explicit limits. School capacity means proposed places, not existing available seats.',{'job_ids':{'type':'array','items':TEXT,'maxItems':6}}),
    function('urban_report','Collect source-backed area summaries, weighted comparisons, captured studies/jobs, unresolved data and next steps for an evidence report.',{}),
    function('workspace_read','Read verified currently selected plan, scenario, parcel, building and floor uses. Call before edits; never invent identifiers.',{}),
    function('plan_list','List saved plans available in this isolated preview.',{}),
    function('plan_open','Open a saved plan ID returned by plan_list; keep existing saved content.',{'plan_id':TEXT}),
    function('plan_create','Create a saved Development plan from 1..6 explicit source parcel IDs. No invented geometry or legal/vacancy claims.',{'name':TEXT,'parcel_ids':IDS}),
    function('scenario_select','Switch to an existing scenario ID from workspace_read.',{'scenario_id':TEXT}),
    function('scenario_duplicate','Duplicate current scenario as an editable comparison alternative; building IDs are copied to new IDs.',{'name':TEXT}),
    function('zoning_edit','Save user-proposed zoning using same workspace validation. action add_type/edit_type payload_json {type:{code,name,color,max_height,max_floors,coverage,far,setback_front,setback_side,setback_rear,source,...},id?}; draw {geometry,type_id,policy:preserve|replace}; assign {zone_ids,type_id}. Read actual IDs from workspace/source first; ask user to draw geometry if absent. Never claim official approval.',{'action':{'type':'string','enum':['add_type','edit_type','draw','assign']},'payload_json':TEXT}),
    function('site_select','Select an existing source parcel or zone:<uuid> inside the current plan.',{'parcel_id':TEXT}),
    function('building_save','Create/update a saved building in current Development scenario. patch_json is a JSON object with BuildingInput fields only: name,floors,floor_height,space_use_id (residential/commercial/office/other),geometry,counts_gfa,counts_far,floor_overrides [{floor,floor_height,space_use_id,counts_gfa,counts_far}]. Existing fields are preserved. Get IDs/geometry from workspace_read; for a new footprint ask user to draw it. Lowering floors requires removing out-of-range overrides explicitly. No deletion or invented coordinates.',{'building_id':NULLTEXT,'patch_json':TEXT}),
    function('source_catalog','Read actual connected map sources and explicit capacity/inventory limitations.',{}),
    function('layer_query','Query system datasets independent of layer visibility: source_catalog lists every supported ID. Supports all vector snapshot layers plus population, historical traffic, sumo_network, saved sumo_simulation, and system poi. For land-price questions use land_price with a disclosed nearby-road radius (typically 1000m); preserve units/date/confidence and never call it parcel market price. Optional parcel_id otherwise selected area. population_year defaults 2026, traffic ISO weekday/hour defaults Tuesday 18h. For sumo_simulation provide an existing run_id or receive the existing run catalog; this never starts a solver. text filters properties and dates apply only to time-enabled vector layers. poi reads actual system map POIs; loaded tiles are not complete city coverage.',{'layer':TEXT,'parcel_id':NULLTEXT,'radius_m':{'type':'number','minimum':0,'maximum':5000},'text':NULLTEXT,'start_date':NULLTEXT,'end_date':NULLTEXT,'population_year':{'type':['integer','null'],'minimum':2010,'maximum':2040},'traffic_weekday':{'type':['integer','null'],'minimum':1,'maximum':7},'traffic_hour':{'type':['integer','null'],'minimum':0,'maximum':23},'run_id':NULLTEXT}),
    function('amenity_site_search','Find real source parcels near supermarkets, parks and/or hospitals for household/site requests, without opening a plan. First choose a neighborhood/visible area. Fetch/cache actual OSM amenities and rank a bounded parcel sample; distances are straight-line, not walking routes. requirements_json is an object of category to maximum meters, e.g. {"supermarket":1000,"park":1000,"hospital":2000}. If user says near without distance, disclose a provisional 1 km radius rather than measured preference. Nullable size bounds use explicit preliminary 40..1000 m2 defaults, not a legal/household requirement. household_people is context only, not enough to design/run a house simulation. Never claim vacancy/buildability. Partial matches are labelled and must not be described as meeting all requirements.',{'requirements_json':TEXT,'household_people':{'type':['integer','null'],'minimum':1,'maximum':100},'minimum_area_m2':{'type':['number','null'],'minimum':1,'maximum':100000},'maximum_area_m2':{'type':['number','null'],'minimum':1,'maximum':100000},'bbox':BOUNDS,'limit':{'type':'integer','minimum':1,'maximum':6}}),
    function('site_context','Read selected source parcel, current building/limit report and nearby flood/price records.',{'parcel_id':NULLTEXT}),
    function('map_control','Request layers and/or a bounded view. Frontend independently verifies source availability before displaying.',{'layer_ids':{'type':'array','items':TEXT},'bbox':BOUNDS}),
    function('simulation_prepare','Freeze current saved Development plan/revision/scenario. settings_json is {} for labelled UI defaults or explicit fields residential_m2_per_person,work_m2_per_staff,visitors_per_100m2_day,green_open_percent,landscape_mode(preserve/redesign),rainfall_mm,traffic_radius_m. No fake capacity. scope parcel requires selected parcel.',{'scope':{'type':'string','enum':['parcel','scenario']},'settings_json':TEXT}),
    function('simulation_start','Start frozen Development inputs. Native dynamically prepares local OSM roads and same before/after background; requires UI authorization. Job asynchronous.',{'prepared_id':TEXT,'mode':MODE}),
    function('simulation_latest','Import most recent completed run matching current plan revision/scenario/scope. Saved assumptions may differ from current controls.',{}),
    function('simulation_results','Read owned/imported jobs, source labels, unknowns and stale revision warning. Compare only completed comparable runs; inspect unfinished/undeparted trips alongside delay.',{'job_ids':{'type':'array','items':TEXT,'maxItems':6}}),
    function('simulation_verify','Run a frozen original/variant pair keeping program, sources, rain and seeds equal. Controls water=efficient_fixtures,power=efficient_equipment,runoff=storage>=50m3,traffic=stagger>=2h. Hypothetical controls do not change map building; traffic needs native. Do not promise benefit before completed results.',{'prepared_id':TEXT,'goal':{'type':'string','enum':['water','power','runoff','traffic']},'mode':MODE}),
]

for tool in TOOLS:
    if tool['name'] in ('candidate_compare','amenity_site_search'):
        tool['parameters']['properties']['travel_mode']={'type':['string','null'],'enum':['car','bike','truck',None]}
        tool['parameters']['required'].append('travel_mode')
        tool['description'] += ' Optional travel_mode car/bike/truck enables Goong V2 route-based accessibility; null preserves straight-line/proxy behavior. Bike retains the provider mode label; do not relabel it cycling/motorcycle without confirmation. Walking and motorcycle are rejected by the verified API enum. For candidate_compare, metrics hospital_travel_seconds,park_travel_seconds,supermarket_travel_seconds,hospital_route_m,park_route_m,supermarket_route_m require an explicit travel_mode. Amenity routing evaluates only the bounded shortlisted parcels, not every mapped parcel.'
    if tool['name']=='area_select':
        tool['description'] += ' source=goong_place searches actual Goong Places using the backend REST key; multiple matches with match_index=null require user choice without changing area. Selected result is a disclosed 1000m buffer around the provider point, NOT a district boundary. Use source=place/confirmed viewport for a district-wide scope. Named street/alley still uses source=street first; Goong can resolve addresses not in that road source.'
    if tool['name']=='dataset_query':
        tool['description'] += ' Each join is required=true by default (inner spatial match): rows without a qualifying source feature are excluded automatically. Set required=false ONLY for explicit optional enrichment/absence-of-record queries. Aggregates count every matched fetched row BEFORE limit; preserve the requested display limit when counting.'
        tool['description'] += ' Warehouse sources now filter/join/count/order in PostGIS BEFORE display LIMIT; external POI/derived adapters retain disclosed bounds. Explicit unit values are allowed: between value={min:20,max:40,unit: million_vnd_per_m2} for *_vnd_m2; scalar {amount:20,unit:million_vnd_per_m2}; area_m2 units m2/ha, distance_m units m/km, duration_s units s/min. Never infer a unit absent from the user request.'
    if tool['name']=='area_select':
        tool['parameters']['properties']['source']['enum'].append('search_place')
        tool['description'] += ' source=search_place uses the actual place selected with Search places in the web, with a disclosed 1000m point buffer. Only when the user explicitly refers to that selected place. source=place requests provider administrative polygon when available, otherwise explicitly labelled bbox; do not substitute a Goong point buffer for a whole district.'

TOOLS.extend([
    function('accessibility_compare','Evaluate 1..6 actual source parcels to mapped supermarkets/parks/hospitals using Goong Distance Matrix V2, up to two nearby mapped POIs/category/parcel. Explicit travel_mode required. Finite POI coverage and representative points, not verified entrances or exhaustive optimum. Unknown/unreachable remains unknown. Use result ID for route_show.',{'parcel_ids':IDS,'categories':{'type':'array','items':{'type':'string','enum':['supermarket','park','hospital']},'minItems':1,'maxItems':3},'travel_mode':{'type':'string','enum':['car','bike','truck']},'radius_m':{'type':'number','minimum':50,'maximum':5000}}),
    function('route_show','Display a Goong Directions V2 route for a parcel/category from an owned accessibility result. Never invent coordinates/destinations or substitute a straight line if routing fails. API duration is not a SUMO impact prediction.',{'accessibility_id':TEXT,'parcel_id':TEXT,'category':{'type':'string','enum':['supermarket','park','hospital']}}),
])
